package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.DefaultAcrValuesVO;

class DefaultAcrValuesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of default acr values of oauth client")
  void test_default_acr_values_value_holder_assign_plain_value() {
    Object holder = new Object();
    DefaultAcrValuesValueHolder<Object> value = new DefaultAcrValuesValueHolder<>(holder);
    Assertions.assertSame(holder, value.defaultAcrValues("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getDefaultAcrValuesValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getDefaultAcrValues().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.defaultAcrValuesNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getDefaultAcrValuesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getDefaultAcrValues().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of default acr values of oauth client")
  void test_default_acr_values_value_holder_assign_value_object() {
    Object holder = new Object();
    DefaultAcrValuesValueHolder<Object> value = new DefaultAcrValuesValueHolder<>(holder);
    DefaultAcrValuesVO vo = DefaultAcrValuesVO.from("one");
    Assertions.assertFalse(value.getDefaultAcrValuesValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.defaultAcrValues(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getDefaultAcrValuesValue().orElseThrow());
    Assertions.assertSame(holder, value.defaultAcrValues(Optional.empty()));
    Assertions.assertFalse(value.getDefaultAcrValuesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.defaultAcrValues(Optional.of(vo)));
    Assertions.assertSame(vo, value.getDefaultAcrValuesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of default acr values of oauth client against the original")
  void test_default_acr_values_value_holder_read() {
    Object holder = new Object();
    DefaultAcrValuesValueHolder<Object> value = new DefaultAcrValuesValueHolder<>(holder);
    DefaultAcrValuesVO vo = DefaultAcrValuesVO.from("one");
    DefaultAcrValuesVO other = DefaultAcrValuesVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getDefaultAcrValuesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readDefaultAcrValues(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readDefaultAcrValues(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.defaultAcrValues(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readDefaultAcrValues(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readDefaultAcrValues(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of default acr values of oauth client")
  void test_default_acr_values_value_holder_unset() {
    Object holder = new Object();
    DefaultAcrValuesValueHolder<Object> value = new DefaultAcrValuesValueHolder<>(holder);
    DefaultAcrValuesVO vo = DefaultAcrValuesVO.from("one");
    value.defaultAcrValues(vo);
    Assertions.assertSame(holder, value.unsetDefaultAcrValuesIfMatches("defaultAcrValues_other"));
    Assertions.assertTrue(value.getDefaultAcrValuesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetDefaultAcrValuesIfMatches("defaultAcrValues"));
    Assertions.assertFalse(value.getDefaultAcrValuesValue().isPresent(),
        "The field name must clear the value");
    value.defaultAcrValues(vo);
    Assertions.assertSame(holder, value.unsetDefaultAcrValues());
    Assertions.assertFalse(value.getDefaultAcrValuesValue().isPresent(),
        "Unset must clear the value");
  }
}
